// Barrel entry for the @molecule-ai/contracts npm package.
//
// This file is the package shim — hand-written and NOT generated. It only
// re-exports the generated bindings alongside it (which ARE generated by
// tools/gen-ts.mjs and must never be hand-edited; the codegen-drift gate
// enforces that). Keeping the shim non-generated leaves generator output
// byte-identical so the drift gate stays green.
//
// This is the FOLDED home of the former molecule-contracts @molecule-ai/contracts
// package: the dist name and its subpath exports (./contract, ./workspace-comms)
// are kept byte-stable so TS consumers need no source change.
//
// Consumers:
//   import { RequiredTool, RegisterRequest } from "@molecule-ai/contracts";
// or the per-domain subpaths:
//   import { RequiredTool } from "@molecule-ai/contracts/contract";
//   import { RegisterRequest } from "@molecule-ai/contracts/workspace-comms";
//   import { IdlePromptContribution } from "@molecule-ai/contracts/idle-prompt";
//
// The idle-prompt layer is re-exported here (and given a subpath) because its
// whole purpose is cross-repo consumption by the molecule_runtime assembler —
// unlike catalog_gen (CP-internal), consumers must be able to import it from
// the published surface, not private file paths. Generated names are prefixed
// (IdlePrompt* / IDLE_PROMPT_*) so `export *` cannot collide.

export * from "./contract_gen";
export * from "./workspace_comms_gen";
export * from "./idle_prompt_gen";
export * from "./runtime_ids.generated";
